"""
Scenario-based and harder questions that fill the gaps found by the coverage report: hard-level items across the syllabus, easy
on-ramps, practical interview scenarios, and short-answer design problems. Design, transaction and SQL answers are machine-checked.
"""

from __future__ import annotations

from app.services.dbms_sql.content.build import mcq as M, outq as O, short as S

SC = "scenario"


def questions() -> list[dict]:
    return [
        # ---- Unit A ----
        M("components-applications", "hard", "A banking app crashes after the debit of a transfer was logged but before the credit. On restart, which DBMS component restores a consistent state, and how?",
          "The recovery manager, by undoing the incomplete transaction from the log", ["The query optimizer, by re-planning the transfer", "The buffer manager, by flushing every page and keeping the result", "The authorization manager, by rolling back the user's privileges"],
          "Crash recovery replays committed work and undoes uncommitted work from the write-ahead log, so the half-done transfer is rolled back.", fmt=SC),
        M("three-tier-architecture", "hard", "A mobile app connects straight to the production database using an admin password embedded in the app. Which change fixes the biggest risk?",
          "Add an application tier (API) that holds the credentials and authorises each user's requests", ["Obfuscate the password inside the app", "Add more indexes to the database", "Move the database to a bigger server"],
          "Anyone can extract an embedded secret. A middle tier keeps credentials server-side and enforces per-user rules.", fmt=SC),
        M("schema-instance", "hard", "A DBA adds a nullable column to a table that holds 10 million rows. In logical terms, what changed?", "The schema changed, and every existing row now has NULL in the new column",
          ["Only the instance changed", "Neither changed", "Only the catalog changed, not the schema"], "The table definition (schema) gained a column, so each row of the instance logically gains a NULL value there.", fmt=SC),
        M("data-modelling", "hard", "Doctors see many patients and patients see many doctors; the date of each visit must be recorded. Where does the date belong in the model?", "On the relationship (appointment) between doctor and patient",
          ["On the doctor entity", "On the patient entity", "In a table unrelated to both"], "The date describes one pairing of a doctor and a patient, so it is an attribute of the many-to-many relationship (a junction table).", fmt=SC),
        M("relational-vs-nonrelational", "hard", "A catalog has thousands of product types, each with different attributes, and products are read one at a time by id. Which store fits most naturally?",
          "A document store, because each product is a self-contained record with variable fields", ["Relational tables with one column for every possible attribute", "A graph database", "A single CSV file"],
          "Variable attributes read together by key suit documents. A relational design would be very sparse or need an entity-attribute-value layout.", fmt=SC),
        # ---- Unit B ----
        M("ddl-dml-dcl-tcl", "hard", "Which script lists a DDL, a DML, a DCL and a TCL statement, in that order?", "CREATE TABLE t (a INT); INSERT INTO t VALUES (1); GRANT SELECT ON t TO u; COMMIT;",
          ["GRANT SELECT ON t TO u; CREATE TABLE t (a INT); COMMIT; INSERT INTO t VALUES (1);", "COMMIT; INSERT INTO t VALUES (1); CREATE TABLE t (a INT); GRANT SELECT ON t TO u;", "INSERT INTO t VALUES (1); GRANT SELECT ON t TO u; CREATE TABLE t (a INT); COMMIT;"],
          "CREATE is DDL, INSERT is DML, GRANT is DCL and COMMIT is TCL; only the first script has them in that order.", fmt=SC),
        M("integrity-constraints", "hard", "orders.customer_id references customers with ON DELETE CASCADE. A customer with 5 orders is deleted. What happens?", "The customer's 5 orders are deleted automatically",
          ["The delete fails", "The orders keep a dangling customer_id", "The orders' customer_id becomes 0"], "CASCADE propagates the delete to referencing rows; RESTRICT or NO ACTION would block it and SET NULL would clear the reference.", fmt=SC),
        M("keys", "hard", "R(A,B,C,D) has AB->C, C->D and D->A. What are all its candidate keys?", "{A, B}, {B, C}, {B, D}", ["{A, B} only", "{B}", "{A}, {C}, {D}"],
          "B appears on no right-hand side, so every key contains B. AB, BC and BD each reach every attribute through the chain, and none can be shortened.", fmt="design",
          ref=("candidate_keys", {"attrs": "ABCD", "fds": "AB->C, C->D, D->A"}), hints=("Which attribute can never be derived?",)),
        O("crud-concepts", "hard", "A developer plans DELETE FROM orders WHERE amount < 100. How many rows will it remove?", "SELECT COUNT(*) FROM orders WHERE amount < 100", "scalar",
          lambda T: str(sum(1 for o in T["orders"] if o["amount"] is not None and o["amount"] < 100)), ["6", "4", "15"],
          "Five orders have an amount below 100. The order with a NULL amount is not removed, because NULL < 100 is unknown, not true.", hints=("Run the equivalent SELECT first.",)),
        O("null-constraint-violations", "hard", "How many rows does this query return?", "SELECT COUNT(*) FROM orders WHERE amount > 100 OR amount <= 100", "scalar",
          lambda T: str(sum(1 for o in T["orders"] if o["amount"] is not None)), ["15", "0", "13"],
          "Together the two conditions look exhaustive, but a NULL amount makes both unknown. The NULL order is excluded: 14 of 15 rows qualify."),
        # ---- Unit C ----
        M("hashing-indexing", "hard", "A table has an index on (last_name, first_name). Which filter can use the index efficiently?", "WHERE last_name = 'Rao' AND first_name LIKE 'A%'",
          ["WHERE first_name = 'Asha'", "WHERE UPPER(last_name) = 'RAO'", "WHERE last_name LIKE '%ao'"], "A composite index serves a leftmost prefix. A function on the column or a leading wildcard prevents ordered lookup, and skipping last_name leaves the index unusable for a seek.", fmt=SC),
        M("query-optimization", "easy", "Orders are often filtered by customer_id and the query is slow. Which change usually helps most?", "Create an index on orders(customer_id)", ["Add ORDER BY with a random key", "Select every column", "Remove the WHERE clause"],
          "An index lets the engine seek the matching rows instead of scanning the whole table.", fmt=SC),
        M("execution-plans", "easy", "In SQLite, a plan line that starts with SCAN means:", "The table is read row by row (no index seek)", ["A primary key lookup", "A covering index is used", "The query is cached"], "SCAN is a full pass over the table (or index); SEARCH means an indexed lookup.", dialect="sqlite"),
        # ---- Unit D ----
        M("functional-dependencies", "hard", "R(A,B,C,D,E) has A->B, BC->D, E->C and D->A. What is the closure of {E, B}?", "{A, B, C, D, E}", ["{B, C, E}", "{B, C, D, E}", "{A, B, E}"],
          "E gives C; B and C give D by BC->D; D gives A by D->A, so everything is reached.", fmt="design", ref=("closure", {"fds": "A->B, BC->D, E->C, D->A", "x": "EB"})),
        M("data-integrity", "hard", "Stock must never be negative even when two sessions update it at the same moment. Which control is most robust?", "A CHECK (qty >= 0) constraint enforced by the database",
          ["A JavaScript check in the browser", "A nightly report that lists negative stock", "Validation in one application server only"], "Only a database-enforced rule applies to every client and every concurrent writer.", fmt=SC),
        M("1nf", "hard", "A CSV import put 'SQL;Python' into one skills cell. Which design satisfies classical 1NF without repeating columns?", "A separate employee_skill(emp_id, skill) table with one skill per row",
          ["Columns skill1, skill2 and skill3", "One wider text column", "One column holding a comma-separated list"], "Repeating columns are still a repeating group, and lists in one cell are not atomic. One row per employee-skill pair is.", fmt=SC),
        M("2nf", "hard", "Order lines are R(A=OrderID, B=ProductID, C=ProductName, D=Qty) with AB->D and B->C. What is the highest normal form?", "1NF", ["2NF", "3NF", "BCNF"],
          "The key is {A, B}. ProductName depends only on ProductID, a partial dependency, so the table is not in 2NF.", fmt="design", ref=("highest_nf", {"attrs": "ABCD", "fds": "AB->D, B->C"})),
        M("3nf", "hard", "R(A,B,C,D,E) has A->B, B->C, A->D and D->E. What is its highest normal form?", "2NF", ["1NF", "3NF", "BCNF"],
          "A is the only key, so there is no partial dependency. B->C and D->E are transitive dependencies of non-prime attributes, which breaks 3NF.", fmt="design",
          ref=("highest_nf", {"attrs": "ABCDE", "fds": "A->B, B->C, A->D, D->E"})),
        M("4nf", "hard", "R(A,B,C) has AB->C and the multivalued dependency A ->> B. Is it in 4NF?", "Not in 4NF", ["In 4NF", "In 4NF because AB is a key", "Only in 3NF terms"],
          "A ->> B is nontrivial (A and B do not cover C) and A is not a superkey, so it violates 4NF.", fmt="design", ref=("in_4nf", {"attrs": "ABC", "fds": "AB->C", "mvds": "A->>B"})),
        M("anomalies", "hard", "Enrollment(student, course, instructor, office) where each instructor has one office. Which decomposition removes the update anomaly for office?",
          "Instructor(instructor, office) and Enrollment(student, course, instructor)", ["Enrollment(student, course) and Office(office)", "Keep one table and add an index on instructor", "Student(student, office) and Course(course, instructor)"],
          "The office is a fact about the instructor, so it should be stored once with the instructor, not repeated in every enrolment row.", fmt=SC),
        M("decomposition-lossless", "easy", "For a lossless-join decomposition, the natural join of the projections gives:", "Exactly the original relation, with no spurious tuples", ["More tuples than the original", "Fewer tuples than the original", "Only the key attributes"],
          "Lossless means nothing is lost or invented when the pieces are joined back together."),
        M("decomposition-lossless", "hard", "R(A,B,C,D,E) has A->C, B->C, C->D, DE->C and CE->A. Is the decomposition AD, AB, BE, CDE, AE lossless?", "Lossless", ["Lossy", "Lossless only for the key", "Not decidable"],
          "The tableau (chase) test ends with a row of all distinguished symbols, so the join reconstructs R. This is a classic textbook example.", fmt="design",
          ref=("lossless", {"attrs": "ABCDE", "fds": "A->C, B->C, C->D, DE->C, CE->A", "decomp": ["AD", "AB", "BE", "CDE", "AE"]})),
        S("functional-dependencies", "medium", "R(A,B,C,D,E) has A->B, B->C and CD->E. Compute the closure of {A, D}.", "attrs", ["A", "B", "C", "D", "E"], "Type the attributes as letters, e.g. ABCDE.",
          "A gives B, B gives C, and C with D gives E, so the closure contains every attribute.", ("closure", {"fds": "A->B, B->C, CD->E", "x": "AD"}), hints=("Keep applying dependencies until nothing new is added.",)),
        S("keys", "medium", "R(A,B,C,D) has A->B and C->D. Give all candidate keys.", "keys", ["AC"], "Type each key as letters; separate several keys with commas, e.g. AB, CD.",
          "A and C appear on no right-hand side, so both are in every key. {A, C} reaches B and D and is minimal.", ("candidate_keys", {"attrs": "ABCD", "fds": "A->B, C->D"})),
        S("keys", "hard", "R(A,B,C) has A->B, B->A and A->C. Give all candidate keys.", "keys", ["A", "B"], "Type each key as letters; separate several keys with commas, e.g. A, BC.",
          "A determines B and C. B determines A, so it also determines everything. Both single attributes are keys.", ("candidate_keys", {"attrs": "ABC", "fds": "A->B, B->A, A->C"})),
        S("normalization-purpose", "hard", "R(A,B,C,D) has AB->C and C->D. List its prime attributes.", "attrs", ["A", "B"], "Type the prime attributes as letters, e.g. AB.",
          "The only candidate key is {A, B}, so A and B are prime; C and D are non-prime. That is why C->D is a transitive dependency.", ("prime_attributes", {"attrs": "ABCD", "fds": "AB->C, C->D"})),
        # ---- Unit E ----
        M("flow-control", "hard", "Which expression returns 'senior' for years >= 10, 'mid' for years >= 3 and otherwise 'junior' in standard SQL?",
          "CASE WHEN years >= 10 THEN 'senior' WHEN years >= 3 THEN 'mid' ELSE 'junior' END", ["CASE WHEN years >= 3 THEN 'mid' WHEN years >= 10 THEN 'senior' ELSE 'junior' END", "CASE years >= 10 'senior' years >= 3 'mid' ELSE 'junior' END", "IF years >= 10 THEN 'senior' ELSEIF years >= 3 THEN 'mid' ELSE 'junior' END IF"],
          "CASE takes the first true branch, so the strictest condition must come first. The second form would label every senior as mid.", fmt=SC),
        M("stored-procedures", "hard", "A procedure moves money with two UPDATE statements and must never leave a half-finished transfer. What should it do?", "Run both statements in one transaction and roll back if either fails",
          ["Commit after each statement", "Catch any error and ignore it", "Run the second update first and hope it works"], "Atomicity needs one transaction around both updates, with a rollback path on error.", fmt=SC),
        M("exception-handling", "hard", "In PL/pgSQL, what happens to changes made earlier in a BEGIN block when its EXCEPTION handler runs?", "They are rolled back, because the block runs in an implicit subtransaction",
          ["They are committed immediately", "They stay until the whole transaction ends", "They are rolled back only for SELECT statements"], "A block with an EXCEPTION clause sets up a savepoint; on error the block's changes are undone before the handler continues.", dialect="postgresql", fmt=SC),
        # ---- Unit F ----
        M("transaction-concepts", "hard", "Two cashiers each run UPDATE accounts SET balance = balance - 100 WHERE id = 7 at the same time on a balance of 500. In a correctly isolated DBMS the final balance is:", "300", ["400", "200", "500"],
          "Isolation serialises the two read-modify-write operations, so both deductions apply: 500 - 100 - 100 = 300 (a lost update would give 400).", fmt=SC, ref=("arithmetic", {"value": 300})),
        M("transaction-states", "hard", "A transaction finished its last statement but the system crashed before its commit record reached stable storage. After restart it is treated as:", "Not committed, and undone during recovery",
          ["Committed, because all statements ran", "Partially committed forever", "Paused and resumed automatically"], "A transaction commits only when its commit record is durable; a partially committed one is rolled back.", fmt=SC),
        M("schedules", "hard", "Four transactions are to be run one after another. How many different serial schedules exist?", "24", ["4", "12", "16"], "There are 4! = 24 orderings.", fmt="transaction", ref=("serial_count", {"n": 4})),
        M("schedules", "hard", "T1 and T2 each have 3 operations. How many interleavings preserve each transaction's own order?", "20", ["6", "9", "36"], "Choose which 3 of the 6 positions belong to T1: C(6,3) = 20.", fmt="transaction", ref=("interleavings", {"lengths": [3, 3]})),
        M("serial-concurrent", "hard", "A schedule is equivalent to the serial order T2 then T1 but not to T1 then T2. What does that equivalence mean?", "Every pair of conflicting operations occurs in the same relative order as in T2, T1",
          ["The transactions use the same number of operations", "Both transactions commit at the same time", "The schedule never reads the same item twice"], "Conflict equivalence compares the order of conflicting operations (same item, at least one write).", fmt=SC),
        M("concurrency-control", "hard", "Under optimistic concurrency control T1 and T2 read the same row; T1 commits a change to it first. What should T2's validation do?", "Abort and retry T2, because the data it read has changed",
          ["Commit T2 anyway", "Block T1", "Ignore the conflict if T2 only reads"], "Validation detects that T2's read set was modified by a transaction that committed after T2 started.", fmt=SC),
        M("deadlocks", "easy", "A deadlock occurs when:", "Two or more transactions each wait for a lock held by another, forming a cycle", ["A query runs for a long time", "A transaction reads uncommitted data", "An index is missing"], "No transaction in the cycle can proceed, so the DBMS must abort one (the victim)."),
        M("deadlocks", "hard", "Three transactions request these locks in order. Which transactions are deadlocked?", "Deadlock: T1, T2, T3", ["No deadlock", "Deadlock: T1, T2", "Deadlock: T2, T3"],
          "T1 waits for T2 (B), T2 waits for T3 (C) and T3 waits for T1 (A): a three-way cycle.", fmt="transaction", code="X1(A) X2(B) X3(C) X1(B) X2(C) X3(A)", ref=("deadlock", {"schedule": "X1(A) X2(B) X3(C) X1(B) X2(C) X3(A)"})),
        M("recoverability", "easy", "A schedule is recoverable if:", "Each transaction commits only after every transaction whose data it read has committed", ["No two transactions touch the same item", "Every transaction commits immediately after starting", "It is a serial schedule only"],
          "Recoverability stops a committed transaction from depending on data that might still be rolled back."),
        M("cascading-rollback", "hard", "T1 aborts. Which transactions must also roll back?", "T2, T3, T4", ["T2 and T3 only", "T2 only", "None"],
          "T2 and T3 read T1's uncommitted A, and T4 read B written by T3, so the rollback cascades through all three.", fmt="transaction", code="W1(A) R2(A) R3(A) W3(B) R4(B) A1",
          ref=("cascade_victims", {"schedule": "W1(A) R2(A) R3(A) W3(B) R4(B) A1", "aborted": 1})),
        M("read-anomalies", "hard", "T1 reads a balance of 100. T2 updates it to 50 and commits. T1 reads it again and sees 50. What is this and which standard level prevents it?",
          "A non-repeatable read, prevented from REPEATABLE READ upward", ["A dirty read, prevented from READ COMMITTED upward", "A phantom read, prevented only by SERIALIZABLE", "A lost update, prevented by READ UNCOMMITTED"],
          "T2's change was committed, so it is not dirty. The same row changed between two reads, which REPEATABLE READ and SERIALIZABLE forbid.", fmt=SC),
        M("isolation-levels", "hard", "Which is the weakest SQL-standard isolation level that prevents non-repeatable reads?", "REPEATABLE READ", ["READ UNCOMMITTED", "READ COMMITTED", "SERIALIZABLE"],
          "READ COMMITTED still allows them. REPEATABLE READ forbids dirty and non-repeatable reads but may allow phantoms.", fmt="transaction", note="Standard definition: REPEATABLE READ is the first SQL-standard level that forbids non-repeatable reads; no machine check applies."),
        # ---- Unit G ----
        M("nosql-concepts", "hard", "During a network partition a store keeps accepting writes on both sides and reconciles them afterwards. In CAP terms it favoured:", "Availability over consistency (AP)",
          ["Consistency over availability (CP)", "Both fully", "Neither"], "Accepting writes everywhere keeps the system available but allows temporary divergence (eventual consistency).", fmt=SC),
        M("mongodb-intro", "hard", "A MongoDB replica set has three data-bearing members and the primary fails. What happens?", "The remaining members hold an election and one becomes the new primary",
          ["Every secondary accepts writes at once", "The set stays read-only until an administrator restarts it", "All data is lost"], "Replica sets provide automatic failover through an election among the surviving voting members.", dialect="mongodb", fmt=SC),
        M("dynamodb-concepts", "hard", "A DynamoDB table uses status (values 'active' or 'closed') as its partition key. What problem is likely at scale?", "Hot partitions, because so few distinct key values concentrate the traffic",
          ["Joins become impossible", "Items can no longer be updated", "The table cannot have a sort key"], "Throughput is spread across partition-key values. A low-cardinality key funnels most requests to a few partitions.", dialect="dynamodb", fmt=SC),
        M("mongodb-structure", "hard", "What happens when you insert a document whose _id already exists in the collection?", "The insert fails with a duplicate key error", ["The old document is silently replaced", "Both documents are kept", "MongoDB changes the new _id"],
          "_id carries a unique index, so a duplicate is rejected unless you explicitly replace or upsert.", dialect="mongodb"),
        M("mongodb-crud", "hard", "Given items = pen/50, book/12, bag/30, how many documents have low: true after this command?", "2", ["3", "1", "0"], "The filter qty < 40 matches book (12) and bag (30); pen (50) is untouched.",
          dialect="mongodb", fmt="output", code="db.items.updateMany({ qty: { $lt: 40 } }, { $set: { low: true } })", note="Result recomputed with mongomock by tests and tools/verify_dbms_bank.py; the explanation is a maintainer-written justification.",
          extra={"mongo_check": {"docs": [{"name": "pen", "qty": 50}, {"name": "book", "qty": 12}, {"name": "bag", "qty": 30}], "op": "update_many_count", "filter": {"qty": {"$lt": 40}}, "update": {"$set": {"low": True}}, "count_filter": {"low": True}, "expected": 2}}),
        M("sql-vs-nosql", "hard", "Checkout must decrement stock and create an order atomically. Which statement is most accurate?", "A relational database does it naturally in one transaction; many NoSQL stores need extra patterns or have narrower transaction support",
          ["NoSQL databases can never run transactions", "SQL databases cannot update several rows atomically", "Neither kind can do it"], "Multi-row ACID transactions are a core relational feature; some document stores offer them with restrictions.", fmt=SC),
        M("mongodb-indexes", "hard", "A query filters on { status: 'A' } and sorts by { date: -1 }. Which index supports both the filter and the sort?", "{ status: 1, date: -1 }", ["{ date: -1 }", "{ status: 1 }", "{ date: 1, status: 1 }"],
          "Equality fields come first, then the sort field, so the index returns matches already in sorted order.", dialect="mongodb", fmt=SC),
        M("explain-query-plans", "easy", "In MongoDB explain output, an IXSCAN stage indicates that:", "An index was scanned to find the matching entries", ["The whole collection was read", "The query failed", "Only the first document was read"], "COLLSCAN is the full collection scan; IXSCAN uses an index.", dialect="mongodb"),
        M("vector-databases", "hard", "Why do vector databases usually use approximate nearest-neighbour indexes such as HNSW instead of exact search?", "Exact search compares against every vector and is too slow at scale; ANN trades a little recall for speed",
          ["Approximate search is always more accurate", "Exact search cannot return similar items", "ANN indexes remove the need for embeddings"], "At millions of vectors, scanning all of them per query is too costly, so graph or partition indexes find near neighbours quickly.", fmt=SC),
    ]
